import {
  MessageContent,
  SendMessageOptions,
  WeChatMessage,
  WeChatPlatform,
  MessageType,
} from "./types";

/**
 * Message formatter for different WeChat platforms
 */
export class MessageFormatter {
  /**
   * Format message for WeChat API
   */
  formatMessage(
    options: SendMessageOptions,
    platform: WeChatPlatform,
    originMsg?: any
  ): WeChatMessage {
    const { toUser, message, recommendQuestions, msgId } = options;
    let content = message.content;

    // Add recommended questions if provided
    if (recommendQuestions && recommendQuestions.length > 0) {
      content = this.withRecommendQuestions(content, recommendQuestions);
    }

    const baseMessage: WeChatMessage = {
      touser: toUser,
      msgtype: message.type,
    };

    // Format based on message type
    if (message.type === MessageType.TEXT) {
      baseMessage.text = { content };
    } else if (message.type === MessageType.IMAGE && message.imageUrl) {
      baseMessage.image = { pic_url: message.imageUrl };
    }

    // Add platform-specific fields
    if (platform === WeChatPlatform.CUSTOM_SERVICE) {
      baseMessage.open_kfid = originMsg?.open_kfid;
      baseMessage.msgid = msgId || originMsg?.msgid;
    }

    return baseMessage;
  }

  /**
   * Append recommended questions to content
   */
  private withRecommendQuestions(
    content: string,
    questions: string[]
  ): string {
    if (!questions || questions.length === 0) {
      return content;
    }
    return `${content}\n\n推荐问题:\n${questions.join("\n")}`;
  }

  /**
   * Split long message into chunks
   */
  splitLongMessage(content: string, maxLength: number = 2000): string[] {
    if (content.length <= maxLength) {
      return [content];
    }

    const chunks: string[] = [];
    let currentChunk = "";

    const lines = content.split("\n");
    for (const line of lines) {
      if ((currentChunk + line).length > maxLength) {
        if (currentChunk) {
          chunks.push(currentChunk.trim());
          currentChunk = "";
        }
        // Handle lines longer than maxLength
        if (line.length > maxLength) {
          for (let i = 0; i < line.length; i += maxLength) {
            chunks.push(line.substring(i, i + maxLength));
          }
        } else {
          currentChunk = line + "\n";
        }
      } else {
        currentChunk += line + "\n";
      }
    }

    if (currentChunk) {
      chunks.push(currentChunk.trim());
    }

    return chunks;
  }
}

