import {
  RunAgentInput,
  BaseEvent,
  EventType,
  AbstractAgent,
  AgentConfig,
} from "@ag-ui/client";
import { Observable } from "rxjs";
import { WeChatSender } from "./wechat-sender";
import {
  WeChatConfig,
  SendMessageOptions,
  MessageType,
  WeChatSendMode,
} from "./types";
import { WeChatHistoryManager, HistoryEntry } from "./wechat-history-manager";
import {
  handleWeChatRetry,
  isContinueCommandValid,
  formatWeChatReplyMessage,
  WeChatReplyMessage,
} from "./wechat-message-handler";
import { aitools, WxSendMessageInput } from "@cloudbase/aiagent-framework";
import { randomUUID } from "crypto";

const AITOOLS = aitools.AITools;

/**
 * Configuration for WeChat Agent Adapter
 */
export interface WeChatAgentConfig extends AgentConfig {
  /**
   * The underlying agent to wrap
   */
  agent: AbstractAgent;

  /**
   * WeChat configuration
   */
  wechatConfig: WeChatConfig;

  /**
   * Optional: Custom message formatter
   * Converts agent output to WeChat message format
   */
  messageFormatter?: (content: string, event: BaseEvent) => SendMessageOptions;

  /**
   * Optional: Filter which events should trigger WeChat messages
   * Default: only TEXT_MESSAGE_CONTENT events
   */
  eventFilter?: (event: BaseEvent) => boolean;

  /**
   * Optional: Recommended questions to show after reply
   */
  recommendQuestions?: string[];

  /**
   * Optional: History manager for saving chat history
   * If not provided, will use singleton instance
   */
  historyManager?: WeChatHistoryManager;
}

interface IWxRunAgentInput extends RunAgentInput {
  forwardedProps: {
    wxSendmessageInput: WxSendMessageInput;
    /** Full user message data from dealMsgData */
    msgData?: {
      recordId: string;
      botId: string;
      conversation: string;
      role: "user" | "assistant";
      content: string;
      type: string;
      triggerSrc: string;
      sender: string;
      needAsyncReply: boolean;
      reply: string;
      originMsg: string;
      recommendQuestions: string[];
      createdAt: number;
    };
    /** Reply metadata for assistant message */
    replay: {
      id: string;
      botId: string;
      conversation: string;
      role: "user" | "assistant";
      content: string;
      type: string;
      triggerSrc: string;
      sender: string;
      needAsyncReply: boolean;
      reply: string;
      originMsg: string;
      recommendQuestions: string[];
      createdAt: number;
    };
  };
}

/**
 * WeChat Agent Adapter
 *
 * Wraps any AbstractAgent and automatically sends its output to WeChat.
 * All methods are proxied to the underlying agent, with the run() method
 * enhanced to capture messages and send them via WeChat.
 *
 * @example
 * ```typescript
 * const myAgent = new SomeAgent({ ... });
 * const wechatAgent = new WeChatAgentAdapter({
 *   agent: myAgent,
 *   wechatConfig: {
 *     platform: 'work',
 *     corpId: 'xxx',
 *     corpSecret: 'xxx'
 *   }
 * });
 *
 * // Use it like any other agent
 * wechatAgent.run(input).subscribe(event => {
 *   // Events are emitted normally
 *   // AND automatically sent to WeChat
 * });
 * ```
 */
export class WeChatAgent extends AbstractAgent {
  private wrappedAgent: AbstractAgent;
  private wechatSender?: WeChatSender;
  private wechatConfig: WeChatConfig;
  private _historyManager: WeChatHistoryManager;
  private messageFormatter: (
    content: string,
    event: BaseEvent
  ) => SendMessageOptions;
  private eventFilter: (event: BaseEvent) => boolean;
  private messageBuffer: string = "";
  private recommendQuestions?: string[];
  public aitools?: aitools.AITools;

  constructor(config: WeChatAgentConfig) {
    super({
      agentId: config.agentId || config.agent.agentId,
      description: config.description || config.agent.description,
      threadId: config.threadId || config.agent.threadId,
      ...config,
    });

    this.wrappedAgent = config.agent;
    this.wechatConfig = config.wechatConfig;
    this.recommendQuestions = config.recommendQuestions;
    this._historyManager =
      config.historyManager || WeChatHistoryManager.getInstance();

    // Initialize sender based on send mode
    const sendMode = config.wechatConfig.sendMode || WeChatSendMode.LOCAL;

    if (sendMode === WeChatSendMode.AITOOLS) {
      // Use aitools SDK (for cloud function environment)
      if (!config.wechatConfig.context) {
        throw new Error("context is required when sendMode is AITOOLS");
      }
      this.aitools = new AITOOLS(config.wechatConfig.context);
    } else {
      // Use local WeChatSender (for local development)
      this.wechatSender = new WeChatSender(config.wechatConfig);
    }

    // Default message formatter
    this.messageFormatter =
      config.messageFormatter ||
      ((content: string) => ({
        toUser: "", // Will be set from originMsg
        message: {
          content: content,
          type: MessageType.TEXT,
        },
        recommendQuestions: this.recommendQuestions,
      }));

    // Default event filter: only TEXT_MESSAGE_CONTENT
    this.eventFilter =
      config.eventFilter ||
      ((event: BaseEvent) => event.type === EventType.TEXT_MESSAGE_CONTENT);
  }

  /**
   * Last assembled reply content after run() completes
   * Controller can read this instead of re-assembling from events
   */
  public lastReply: string = "";

  /**
   * Whether last run had an error
   */
  public lastRunHadError: boolean = false;

  /**
   * Get previous reply from history
   * Used for: retry detection, "继续" command
   */
  async getPreviousReply(
    conversation: string,
    recordId?: string | null
  ): Promise<HistoryEntry | null> {
    return this._historyManager.getPreviousReply(conversation, recordId);
  }

  /**
   * Update message content in history
   */
  async updateHistoryContent(
    messageId: string,
    content: string,
    threadId: string
  ): Promise<void> {
    await this._historyManager.updateContent(threadId, messageId, content);
  }

  /**
   * Handle unverified account logic (WXSubscription/WXService)
   * Handles "继续" command and 11-second retry
   * Uses existing functions from wechat-message-handler.ts
   * @returns { needSkipAI, replyContent, isEnd }
   */
  async handleUnverifiedChat(params: {
    content: string;
    conversation: string;
    previousReply: HistoryEntry | null;
    callbackData: WxSendMessageInput;
    triggerSrc: string;
  }): Promise<{ needSkipAI: boolean; replyContent: string; isEnd: boolean }> {
    const { content, conversation, previousReply, callbackData, triggerSrc } =
      params;

    // Check if async reply already sent (for retry scenario)
    if (previousReply && previousReply.needAsyncReply) {
      return { needSkipAI: true, replyContent: "", isEnd: true };
    }

    // Handle "继续" command
    if (content === "continue" || content === "继续") {
      const latest = await this._historyManager.getPreviousReply(conversation);
      let replyContent = "";

      if (!latest) {
        replyContent = "未找到相关回答，请先发送消息";
      } else if (isContinueCommandValid(latest)) {
        replyContent = latest.content || '正在思考中，请稍后再回复"继续"';
      } else {
        replyContent = "回答已过期，请重新发送消息";
      }

      return { needSkipAI: true, replyContent, isEnd: false };
    }

    // Handle 11-second retry using existing function
    if (previousReply) {
      const result = await handleWeChatRetry(
        previousReply,
        callbackData,
        triggerSrc as any
      );
      return {
        needSkipAI: result.shouldSkip,
        replyContent: result.content || "",
        isEnd: false,
      };
    }

    return { needSkipAI: false, replyContent: "", isEnd: false };
  }

  /**
   * Run method with WeChat integration
   * Wraps the underlying agent's run() and sends messages to WeChat
   */
  run(input: IWxRunAgentInput): Observable<BaseEvent> {
    return new Observable<BaseEvent>((subscriber: any) => {
      this.messageBuffer = "";
      this.lastReply = "";
      this.lastRunHadError = false;
      let errorMessage = "";
      let subscription: any;

      const replyId = input?.forwardedProps?.replay.id || randomUUID();
      Promise.all([
        this.saveInputToHistory(input),
        this.saveReplyToHistory(
          {
            id: replyId,
            content: this.lastReply,
          },
          input
        ),
      ]).then(
        () => {
          // Subscribe to the wrapped agent's events
          subscription = this.wrappedAgent.run(input).subscribe({
            next: (event: BaseEvent) => {
              // Emit the event to our subscribers
              subscriber.next(event);

              // Track if error occurred and capture error message
              if (event.type === EventType.RUN_ERROR) {
                this.lastRunHadError = true;
                const errorEvent = event as any;
                errorMessage =
                  errorEvent.message ||
                  errorEvent.error?.message ||
                  "处理消息时发生错误，请稍后重试";
              }

              // Handle WeChat sending
              this.handleWeChatSending(event, input);
            },
            error: (error: any) => {
              subscriber.error(error);
            },
            complete: () => {
              // Set lastReply for controller to read
              this.lastReply = this.lastRunHadError
                ? errorMessage
                : this.messageBuffer.trim() || "";

              // Send final message if buffer has content and no error occurred
              // (error message already sent in handleWeChatSending)
              if (this.messageBuffer.trim() && !this.lastRunHadError) {
                this.sendToWeChat(this.messageBuffer, input).catch(
                  console.error
                );
              }

              // Auto-save reply to history at complete
              this.saveReplyToHistory(
                {
                  id: input?.forwardedProps?.replay.id || randomUUID(),
                  content: this.lastReply,
                },
                input
              ).catch(console.error);

              subscriber.complete();
            },
          });
        },
        (e) => {
          subscriber.error(e);
        }
      );

      // Return cleanup function
      return () => {
        subscription?.unsubscribe();
      };
    });
  }

  /**
   * Save input message to history at the start of run()
   * Only saves if the last message is from user role
   * Uses msgData from forwardedProps for complete data (similar to dealMsgData)
   */
  private async saveInputToHistory(input: IWxRunAgentInput): Promise<void> {
    const messages = input.messages;
    if (!messages || messages.length === 0) return;

    // Only process if the last message is from user
    const lastMessage = messages[messages.length - 1];
    if (lastMessage.role !== "user") return;

    const { threadId, runId } = input;
    const msgData = input.forwardedProps?.msgData;

    // Use msgData.recordId if available, otherwise fallback to lastMessage.id
    const messageId =
      msgData?.recordId ||
      lastMessage.id ||
      (lastMessage as any).messageId ||
      randomUUID();

    // Extract content from the last user message
    const rawContent = lastMessage.content;
    const content =
      typeof rawContent === "string"
        ? rawContent
        : Array.isArray(rawContent)
          ? rawContent
              .filter((c: any) => c.type === "text")
              .map((c: any) => c.text)
              .join("")
          : "";

    if (threadId && content) {
      await this._historyManager.saveToHistory({
        messageId,
        role: "user",
        content,
        threadId,
        runId,
        createdAt: msgData?.createdAt || Date.now(),
        // Additional fields from msgData (similar to dealMsgData)
        botId: msgData?.botId,
        needAsyncReply: msgData?.needAsyncReply,
        type: msgData?.type,
        metadata: {
          sender: msgData?.sender,
          triggerSrc: msgData?.triggerSrc,
          originMsg: msgData?.originMsg,
          reply: msgData?.reply,
          recommendQuestions: msgData?.recommendQuestions,
        },
      });
    }
  }

  /**
   * Handle WeChat message sending based on events
   */
  private handleWeChatSending(event: BaseEvent, input: IWxRunAgentInput): void {
    // Always handle RUN_ERROR regardless of eventFilter
    if (event.type === EventType.RUN_ERROR) {
      const errorEvent = event as any;
      const errorMessage =
        errorEvent.message ||
        errorEvent.error?.message ||
        "处理消息时发生错误，请稍后重试";
      // Clear buffer to prevent duplicate sending
      this.messageBuffer = "";
      // Send error message to WeChat
      this.sendToWeChat(errorMessage, input).catch(console.error);
      return;
    }

    // Check if this event should trigger WeChat sending
    if (!this.eventFilter(event)) {
      return;
    }

    // Handle different event types
    switch (event.type) {
      case EventType.TEXT_MESSAGE_CONTENT:
        // Accumulate text content
        const content = (event as any).delta || (event as any).content || "";
        this.messageBuffer += content;
        break;

      case EventType.TEXT_MESSAGE_END:
        // Send accumulated message
        if (this.messageBuffer.trim()) {
          this.sendToWeChat(this.messageBuffer, input).catch(console.error);
          this.messageBuffer = "";
        }
        break;
    }
  }

  /**
   * Send message to WeChat and save to history
   * Only sends in async mode (needAsyncReply=true)
   * For sync mode, message is returned via HTTP response by controller
   */
  private async sendToWeChat(
    content: string,
    input: IWxRunAgentInput
  ): Promise<void> {
    try {
      // Check if async reply is needed from originMsg
      const needAsyncReply =
        input.forwardedProps?.replay.needAsyncReply ?? true;

      // Only send via adapter in async mode
      // In sync mode, controller handles returning the message via HTTP response
      if (needAsyncReply) {
        const sendMode = this.wechatConfig.sendMode || WeChatSendMode.AITOOLS;

        if (sendMode === WeChatSendMode.AITOOLS) {
          // Use aitools SDK to send message
          await this.sendViaAITools(content, input);
        } else {
          // Use local WeChatSender to send message
          await this.sendViaLocalSender(content, input);
        }
      }
    } catch (error) {
      console.error("Failed to send message to WeChat:", error);
    }
  }

  /**
   * Save reply content to history
   * Uses replay metadata from forwardedProps for complete data (similar to dealMsgData)
   */
  private async saveReplyToHistory(
    reply: { id: string; content: string },
    input: IWxRunAgentInput
  ): Promise<void> {
    const { threadId, runId } = input;
    const replay = input.forwardedProps?.replay;
    const msgData = input.forwardedProps?.msgData;

    const messageId = reply.id;

    if (threadId && messageId) {
      await this._historyManager.saveToHistory({
        id: messageId,
        messageId,
        role: "assistant",
        content: reply.content,
        threadId,
        runId,
        createdAt: Date.now(),
        // Additional fields from replay/msgData (similar to dealMsgData replyMsgData)
        botId: replay?.botId || msgData?.botId,
        needAsyncReply: replay?.needAsyncReply,
        type: replay?.type || "text",
        metadata: {
          sender: replay?.sender || msgData?.sender,
          triggerSrc: replay?.triggerSrc || msgData?.triggerSrc,
          // For assistant, reply field is empty, replyTo points to user message
          replyTo: (replay as any)?.replyTo || msgData?.recordId,
          originMsg: replay?.originMsg,
          reply: replay?.reply,
          recommendQuestions: replay?.recommendQuestions,
        },
      });
    }
  }

  /**
   * Send message via aitools SDK (for cloud function environment)
   */
  private async sendViaAITools(
    content: string,
    input: IWxRunAgentInput
  ): Promise<void> {
    if (!this.aitools) {
      throw new Error("aitools is not initialized");
    }

    // Get origin message from forwardedProps
    const wxSendmessageInput = input.forwardedProps?.wxSendmessageInput;
    if (!wxSendmessageInput) {
      console.warn(
        "wxSendmessageInput not found in forwardedProps, skipping aitools send"
      );
      return;
    }

    // Process reply message to get correct format for different platforms
    const toWxMsgData = this.processReplyMsg(wxSendmessageInput, content);
    if (!toWxMsgData) {
      console.warn("Failed to process reply message, skipping send");
      return;
    }

    // Extract trigger source
    const triggerSrc =
      wxSendmessageInput.triggerSrc || this.wechatConfig.platform;

    // Send message using aitools
    await this.aitools.sendWxClientMessage(
      this.agentId || "agent",
      triggerSrc,
      {
        msgType: toWxMsgData.msgType,
        touser: toWxMsgData.toUserName,
        text: {
          content: toWxMsgData.content,
        },
        openKfId: toWxMsgData.openKfId,
        msgId: toWxMsgData.msgId || "",
      }
    );
  }

  /**
   * Format reply message for WeChat HTTP response (sync mode)
   * Public method for controller to use
   */
  formatReplyMessage(
    callbackData: any,
    triggerSrc: string,
    content: string
  ): WeChatReplyMessage {
    return formatWeChatReplyMessage(callbackData, triggerSrc, content);
  }

  /**
   * Process reply message to get correct format for different WeChat platforms
   * Based on chat_wx.service.ts processReplyMsg implementation
   */
  private processReplyMsg(
    wxSendMessageInput: WxSendMessageInput,
    content: string
  ) {
    const triggerSrc =
      wxSendMessageInput.triggerSrc || this.wechatConfig.platform;
    const callbackData: any = wxSendMessageInput.callbackData;

    return formatWeChatReplyMessage(callbackData, triggerSrc, content);
  }

  /**
   * Send message via local WeChatSender (for local development)
   */
  private async sendViaLocalSender(
    content: string,
    input: RunAgentInput
  ): Promise<void> {
    if (!this.wechatSender) {
      throw new Error("wechatSender is not initialized");
    }

    const messageOptions = this.messageFormatter(content, {
      type: EventType.TEXT_MESSAGE_CONTENT,
      content,
    } as any);

    // Get origin message from forwardedProps if available
    const originMsg = input.forwardedProps?.originMsg;

    await this.wechatSender.send(messageOptions, originMsg);
  }
}
