/**
 * WeChat Chat History Manager
 * Manages chat history for "continue" command and retry logic
 * Uses CloudBase database storage
 */

import tcb from "@cloudbase/node-sdk";

// Re-export ChatHistoryRecord for convenience
export type { ChatHistoryRecord } from "./wechat-message-handler";

/** Default collection name for chat history */
export const WX_CHAT_HISTORY_COLLECTION = "wx_chat_history";

/**
 * Message role type
 */
export type MessageRole = "user" | "assistant" | "system";

/**
 * Metadata for history entry (stored in metadata field)
 */
export interface HistoryEntryMetadata {
  /** Sender identifier */
  sender?: string;
  /** Trigger source (WXSubscription, WXService, etc.) */
  triggerSrc?: string;
  /** Original message data */
  originMsg?: string;
  /** Reply to message ID */
  replyTo?: string;
  /** Reply message ID */
  reply?: string;
  /** Image URL if applicable */
  image?: string;
  /** Recommended questions */
  recommendQuestions?: string[];
}

/**
 * History entry for storage
 * Contains message info plus optional metadata
 */
export interface HistoryEntry {
  id?: string;
  /** Unique message ID (record_id in database) */
  messageId: string;
  /** Message role: user, assistant, or system */
  role: MessageRole;
  /** Message content */
  content?: string;
  /** Thread/Conversation ID */
  threadId: string;
  /** Creation timestamp */
  createdAt: number;
  /** Bot ID */
  botId?: string;
  /** Run ID for tracking agent runs */
  runId?: string;
  /** Whether async reply is needed (WeChat specific) */
  needAsyncReply?: boolean;
  /** Message status: pending, done, error, cancel */
  status?: string;
  /** Message type */
  type?: string;
  /** Additional metadata */
  metadata?: HistoryEntryMetadata;
}

/**
 * Database document structure (snake_case for CloudBase)
 */
interface ChatHistoryData {
  _id?: string;
  bot_id: string;
  record_id: string;
  role: string;
  status?: string;
  content?: string;
  conversation: string;
  type?: string;
  trace_id?: string;
  async_reply?: boolean;
  metadata?: HistoryEntryMetadata;
  createdAt: number;
  updatedAt: number;
}

export interface HistoryManagerConfig {
  /** CloudBase environment ID */
  envId?: string;
  /** CloudBase secret ID */
  secretId?: string;
  /** CloudBase secret key */
  secretKey?: string;
  /** CloudBase session token */
  token?: string;
  /** Collection name, default: wx_chat_history */
  collectionName?: string;
  /** Bot ID for filtering */
  botId?: string;
}

/**
 * Transform HistoryEntry to database document format
 */
function entryToData(entry: HistoryEntry): Omit<ChatHistoryData, "_id"> {
  return {
    bot_id: entry.botId || "",
    record_id: entry.messageId,
    role: entry.role,
    status: entry.status,
    content: entry.content,
    conversation: entry.threadId,
    type: entry.type,
    trace_id: entry.runId,
    async_reply: entry.needAsyncReply,
    metadata: entry.metadata,
    createdAt: entry.createdAt || Date.now(),
    updatedAt: Date.now(),
  };
}

/**
 * Transform database document to HistoryEntry
 */
function dataToEntry(data: ChatHistoryData): HistoryEntry {
  return {
    id: data._id,
    messageId: data.record_id,
    role: data.role as MessageRole,
    content: data.content,
    threadId: data.conversation,
    createdAt: data.createdAt,
    botId: data.bot_id,
    runId: data.trace_id,
    needAsyncReply: data.async_reply,
    status: data.status,
    type: data.type,
    metadata: data.metadata,
  };
}

/**
 * WeChat History Manager
 * Uses CloudBase database storage
 * Singleton pattern for shared history across adapter and controller
 */
export class WeChatHistoryManager {
  private static instance: WeChatHistoryManager;
  private tcbClient: tcb.CloudBase;
  private collectionName: string;
  private botId: string;
  private collectionReady = false;

  private constructor(config?: HistoryManagerConfig) {
    this.collectionName = config?.collectionName || WX_CHAT_HISTORY_COLLECTION;
    this.botId = config?.botId || "default";

    // Initialize CloudBase client
    const envId =
      config?.envId || process.env.TCB_ENV || process.env.CLOUDBASE_ENV;
    if (!envId) {
      throw new Error(
        "[WeChatHistoryManager] envId is required. Set TCB_ENV or CLOUDBASE_ENV environment variable, or pass envId in config."
      );
    }

    this.tcbClient = tcb.init({
      env: envId,
      secretId: config?.secretId,
      secretKey: config?.secretKey,
      sessionToken: config?.token,
    });
  }

  static getInstance(config?: HistoryManagerConfig): WeChatHistoryManager {
    if (!WeChatHistoryManager.instance) {
      WeChatHistoryManager.instance = new WeChatHistoryManager(config);
    }
    return WeChatHistoryManager.instance;
  }

  /**
   * Ensure collection exists, create if not
   */
  private async ensureCollection(): Promise<void> {
    if (this.collectionReady) return;

    try {
      const db = this.tcbClient.database();
      await db.createCollection(this.collectionName);
      this.collectionReady = true;
    } catch (error: any) {
      // Collection already exists (error code -502005)
      if (error?.code === "DATABASE_COLLECTION_ALREADY_EXIST") {
        this.collectionReady = true;
      } else {
        console.error(
          "[WeChatHistoryManager] Failed to create collection:",
          error
        );
        throw error;
      }
    }
  }

  /**
   * Get previous reply from history
   */
  async getPreviousReply(
    threadId: string,
    messageId?: string | null
  ): Promise<HistoryEntry | null> {
    await this.ensureCollection();
    const db = this.tcbClient.database();
    const _ = db.command;
    const collection = db.collection(this.collectionName);

    const whereCondition: Record<string, any> = {
      conversation: _.eq(threadId),
    };

    if (messageId) {
      whereCondition.record_id = _.eq(messageId);
    }

    const result = await collection
      .where(whereCondition)
      .orderBy("createdAt", "desc")
      .limit(1)
      .get();

    if (result.data && result.data.length > 0) {
      return dataToEntry(result.data[0] as ChatHistoryData);
    }
    return null;
  }

  /**
   * Save record to history
   */
  async saveToHistory(record: HistoryEntry): Promise<void> {
    await this.ensureCollection();
    const db = this.tcbClient.database();
    const _ = db.command;
    const collection = db.collection(this.collectionName);

    // Check if record exists
    const existing = await collection
      .where({ record_id: _.eq(record.messageId) })
      .limit(1)
      .get();

    const data = entryToData({ ...record, botId: record.botId || this.botId });

    if (existing.data && existing.data.length > 0) {
      // Update existing record
      await collection
        .where({ record_id: _.eq(record.messageId) })
        .update(data);
    } else {
      // Add new record
      await collection.add(data);
    }
  }

  /**
   * Update record content by messageId
   */
  async updateContent(
    _threadId: string,
    messageId: string,
    content: string
  ): Promise<void> {
    await this.ensureCollection();
    const db = this.tcbClient.database();
    const _ = db.command;
    const collection = db.collection(this.collectionName);

    await collection.where({ record_id: _.eq(messageId) }).update({
      content,
      updatedAt: Date.now(),
    });
  }
}

// Export singleton getter for convenience
export const getHistoryManager = WeChatHistoryManager.getInstance;
