/**
 * WeChat Message Controller
 * Using @cloudbase/agent-adapter-wx for message processing
 * Directly using sendMessageAGUI handler from @cloudbase/agent-server
 */

import type { Request, Response } from "express";
import {
  validateMessageType,
  extractMsgType,
  getWxChatContent,
  dealMsgData,
  formatWeChatReplyMessage,
  VoiceMessageHandler,
  WeChatTriggerSrc,
} from "../wechat-message-handler";
import { WeChatAgent } from "../agent";
import { v4 as uuidv4 } from "uuid";
import { agui } from "@cloudbase/agent-server";
import type { Logger } from "@cloudbase/agent-shared";
import { noopLogger } from "@cloudbase/agent-shared";
import { EventType } from "@ag-ui/client";
export {
  type Logger,
  type LogFn,
  noopLogger,
  createConsoleLogger,
} from "@cloudbase/agent-shared";

import { AbstractAgent } from "@ag-ui/client";
import { utils, WxSendMessageInput } from "@cloudbase/aiagent-framework";

/**
 * Agent creator function return type
 */
interface AgentCreatorResult {
  agent: AbstractAgent | WeChatAgent | { toAGUIAgent(): AbstractAgent };
  cleanup?: () => void;
}

/**
 * Agent creator function type
 */
type AgentCreator = (params: {
  request: Request;
  options?: { agentId: string };
}) => AgentCreatorResult | Promise<AgentCreatorResult>;

/**
 * Handler options
 */
interface WxMessageHandlerOptions {
  logger?: Logger;
}

/**
 * Extract service name from hostname by finding version number pattern
 * e.g., "my-service-123456" -> "my-service"
 */
function getServiceNameFromHostname(hostname: string): string {
  const parts = hostname.split("-");
  // Find the last part that is purely numeric (version number)
  // Use reverse loop for ES2015 compatibility (instead of findLastIndex)
  let versionIdx = -1;
  for (let i = parts.length - 1; i >= 0; i--) {
    if (/^\d+$/.test(parts[i])) {
      versionIdx = i;
      break;
    }
  }
  return versionIdx > 0 ? parts.slice(0, versionIdx).join("-") : hostname;
}

/**
 * Get bot ID from multiple sources
 * Priority: SCF_FUNCTIONNAME > URL (parsed) > HOSTNAME (parsed) > fallback
 */
function getBotId(url?: string, fallback = "agent-id"): string {
  // 1. SCF function name (highest priority)
  if (process.env.SCF_FUNCTIONNAME) {
    return process.env.SCF_FUNCTIONNAME;
  }
  // 2. Parse from URL using utils
  if (url) {
    const parsedBotId = utils.parseBotId(url);
    if (parsedBotId) {
      return parsedBotId;
    }
  }
  // 3. Parse from HOSTNAME
  if (process.env.HOSTNAME) {
    return getServiceNameFromHostname(process.env.HOSTNAME);
  }
  return fallback;
}

/**
 * Create WeChat message handler
 * Directly using sendMessageAGUI.handler from @cloudbase/agent-server
 * Aligned with chat_wx_v2.service.ts logic
 *
 * @param createAgent - Function to create agent instance (returns { agent, cleanup?})
 * @param options - Handler options
 * @returns Express route handler
 */
export function createWxMessageHandler(
  createAgent: AgentCreator,
  options?: WxMessageHandlerOptions
): (req: Request, res: Response) => Promise<Response> {
  const { logger: parentLogger = noopLogger } = options ?? {};
  const adapterLogger =
    parentLogger.child?.({ component: "sendWXMessageAGUI" }) ?? parentLogger;

  return async (req: Request, res: Response): Promise<Response> => {
    let cleanup: (() => void) | null = null;
    let agent: WeChatAgent = undefined as any;
    const { callbackData } = utils.transformKeysToCamelCase(req.body);
    const { triggerSrc, wxVerify } = utils.parseWxEnvParam({
      httpContext: {
        headers: req.headers,
      },
    } as any) as {
      triggerSrc: WeChatTriggerSrc;
      wxVerify: boolean;
    };
    const wxSendmessageInput: WxSendMessageInput = {
      callbackData,
      triggerSrc,
      wxVerify,
    };
    const requestId = uuidv4();
    const logger = adapterLogger.child?.({ requestId }) ?? adapterLogger;
    const botId = getBotId(
      `${req.protocol}://${req.get("host")}${req.originalUrl}`,
      "agent-wx-send-message"
    );
    try {
      if (!callbackData || !triggerSrc) {
        return res.status(400).json({
          error: "Bad Request",
          message: "Missing required fields: callbackData, triggerSrc",
        });
      }

      logger.info?.("[WX] Received message:", { triggerSrc, wxVerify, botId });

      // 1. Create agent instance first (needed for history and voice handling)
      const { agent: unknownAgent, cleanup: agentCleanup } =
        await Promise.resolve(
          createAgent({ request: req, options: { agentId: botId } })
        );
      cleanup = agentCleanup ?? null;
      agent = (
        "toAGUIAgent" in unknownAgent
          ? unknownAgent.toAGUIAgent()
          : unknownAgent
      ) as WeChatAgent;

      // 2. Process message data (aligned with beforeStream)
      const { msgData, replyMsgData } = dealMsgData(
        callbackData,
        triggerSrc,
        wxVerify,
        botId
      );
      let skipAI = false;
      let isEnd = false;

      // 3. Validate message type
      const msgType = extractMsgType(callbackData);
      const validation = validateMessageType(msgType);

      if (!validation.isValid) {
        skipAI = true;
        replyMsgData.content =
          validation.userErrorMessage || "暂不支持该消息类型";
      }

      // 4. Initialize history and check previous reply (for duplicate/retry)
      const previousReply = await agent.getPreviousReply(
        replyMsgData.conversation,
        replyMsgData.recordId
      );

      // 5. Extract content using package utility (ASYNC)
      const voiceHandler: VoiceMessageHandler = async (
        vBotId: string,
        vTriggerSrc: string,
        mediaId: string
      ) => {
        try {
          const result = await agent?.aitools?.getWxMediaContent(
            vBotId,
            vTriggerSrc,
            mediaId
          );

          return result || null;
        } catch {
          return null;
        }
      };

      const content = await getWxChatContent(
        callbackData,
        triggerSrc,
        voiceHandler,
        botId
      );

      // 6. Handle unverified account logic (WXSubscription/WXService only)
      if (
        ["WXSubscription", "WXService"].includes(triggerSrc) &&
        !wxVerify &&
        !skipAI
      ) {
        const result = await agent.handleUnverifiedChat({
          content,
          conversation: replyMsgData.conversation,
          previousReply,
          callbackData,
          triggerSrc,
        });
        skipAI = result.needSkipAI;
        isEnd = result.isEnd;
        if (result.replyContent) replyMsgData.content = result.replyContent;
      }

      // 7. Early return: async reply already sent
      if (isEnd) {
        return res.json({});
      }

      // 8. Early return: empty content
      if (!content && !skipAI) {
        logger.warn?.("[WX] Empty content");
        return res.json(
          formatWeChatReplyMessage(callbackData, triggerSrc, "无法识别消息内容")
        );
      }

      // 9. Early return: skipAI
      if (skipAI) {
        logger.info?.("[WX] Skipping AI");
        return res.json(
          formatWeChatReplyMessage(
            callbackData,
            triggerSrc,
            replyMsgData.content
          )
        );
      }

      // 10. Prepare input for sendMessageAGUI.handler
      // History is auto-managed by adapter.run():
      //   - Input message saved at start
      //   - Reply saved at complete
      logger.info?.("[WX] Processing:", content.substring(0, 100));
      const input = {
        messages: [
          {
            id: msgData.recordId,
            role: "user" as const,
            content,
          },
        ],
        state: undefined,
        threadId: msgData.conversation,
        runId: uuidv4(),
        tools: [],
        context: [],
        forwardedProps: {
          wxSendmessageInput,
          // Pass full msgData for history storage
          msgData: msgData,
          // Pass replay info with replyMsgData for assistant history
          replay: {
            id: replyMsgData.recordId,
            ...replyMsgData,
          },
        },
      };

      // 13. Call agent - WeChatAgentAdapter.run() handles:
      //     - Message assembly (both modes)
      //     - Message sending (async mode only)
      //     - History saving (both modes)
      //     - Error handling (async mode: sends error message)
      const events = agui.sendMessageAGUI.handler(input, agent);

      // 14. Consume events to trigger adapter processing
      for await (const event of events) {
        if (event.type === EventType.RUN_ERROR) {
          logger.error?.(
            "[WX] Agent error:",
            (event as any).error || (event as any).message
          );
        }
      }
      logger.info?.("[WX] Processing complete");

      // 15. Return response - get assembled reply from agent
      if (replyMsgData.needAsyncReply) {
        // Async mode: message already sent by adapter
        return res.json({});
      }
      // Sync mode: get assembled reply from agent and return via HTTP
      const finalContent = agent.lastReply || "抱歉，无法生成回复";
      return res.json(
        formatWeChatReplyMessage(callbackData, triggerSrc, finalContent)
      );
    } catch (error) {
      logger.error?.("[WX] Error processing message:", error);
      const message = error instanceof Error ? error.message : String(error);
      try {
        if (agent?.aitools?.sendWxClientMessage) {
          const data = formatWeChatReplyMessage(
            callbackData,
            triggerSrc,
            message
          );
          await agent.aitools.sendWxClientMessage(
            agent.agentId || botId,
            triggerSrc,
            {
              msgType: data.msgType,
              touser: data.toUserName,
              text: {
                content: data.content,
              },
              openKfId: data.openKfId,
              msgId: data.msgId,
            }
          );
        }
      } catch (e) {}
      return res.status(500).json({
        error: "Internal Server Error",
        message,
      });
    } finally {
      if (cleanup) cleanup();
    }
  };
}
