import {
  WeChatConfig,
  WeChatMessage,
  WeChatPlatform,
  WeChatAPIResponse,
} from "./types";
import { TokenManager } from "./token-manager";

/**
 * Platform router for sending messages to different WeChat platforms
 */
export class PlatformRouter {
  private tokenManager: TokenManager;

  constructor(tokenManager: TokenManager) {
    this.tokenManager = tokenManager;
  }

  /**
   * Send message to WeChat platform
   */
  async send(
    message: WeChatMessage,
    config: WeChatConfig
  ): Promise<WeChatAPIResponse> {
    const accessToken = await this.tokenManager.getAccessToken(config);

    switch (config.platform) {
      case WeChatPlatform.CUSTOM_SERVICE:
        return this.sendToCustomService(message, accessToken, config);
      case WeChatPlatform.MINI_APP:
        return this.sendToMiniApp(message, accessToken);
      case WeChatPlatform.SERVICE:
      case WeChatPlatform.SUBSCRIPTION:
        return this.sendToOfficialAccount(message, accessToken);
      default:
        throw new Error(`Unsupported platform: ${config.platform}`);
    }
  }

  /**
   * Send to Enterprise WeChat Customer Service
   */
  private async sendToCustomService(
    message: WeChatMessage,
    accessToken: string,
    config: WeChatConfig
  ): Promise<WeChatAPIResponse> {
    const url = `https://qyapi.weixin.qq.com/cgi-bin/kf/send_msg?access_token=${accessToken}`;
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(message),
    });
    return response.json();
  }

  /**
   * Send to WeChat Mini Program
   */
  private async sendToMiniApp(
    message: WeChatMessage,
    accessToken: string
  ): Promise<WeChatAPIResponse> {
    const url = `https://api.weixin.qq.com/cgi-bin/message/custom/send?access_token=${accessToken}`;
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(message),
    });
    return response.json();
  }

  /**
   * Send to WeChat Official Account (Service/Subscription)
   */
  private async sendToOfficialAccount(
    message: WeChatMessage,
    accessToken: string
  ): Promise<WeChatAPIResponse> {
    const url = `https://api.weixin.qq.com/cgi-bin/message/custom/send?access_token=${accessToken}`;
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(message),
    });
    return response.json();
  }
}

