/**
 * WeChat Message Handler - 微信消息处理工具
 *
 * 处理调用模型之前的所有逻辑：
 * - 消息类型校验
 * - 内容提取
 * - 消息数据生成
 * - 发送者/会话提取
 */

import { WxSendMessageInput } from "@cloudbase/aiagent-framework";
import { HistoryEntry } from "./wechat-history-manager";
import { WeChatPlatform } from "./types";

// ============================================================================
// Types - 类型定义
// ============================================================================

/**
 * WeChat message input - 微信公众号/服务号/小程序消息
 */
export interface WeChatCommonInput {
  toUserName: string;
  fromUserName: string;
  createTime: number;
  msgType: string;
  msgId: string;
  content?: string; // 文本消息
  mediaId?: string; // 语音消息
  recognition?: string; // 语音识别结果
}

/**
 * WeChat Work customer service message input - 企业微信客服消息
 */
export interface WeChatWorkCommonInput {
  toUserName?: string;
  externalUserId: string;
  openKfId: string;
  msgType: string;
  msgId: string;
  sendTime: number;
  text?: { content: string };
  voice?: { mediaId: string };
}

/**
 * Supported trigger sources - 支持的触发源
 */
export type WeChatTriggerSrc =
  | WeChatPlatform.SUBSCRIPTION // 微信订阅号
  | WeChatPlatform.SERVICE // 微信服务号
  | WeChatPlatform.MINI_APP // 微信小程序
  | WeChatPlatform.CUSTOM_SERVICE; // 企业微信客服

/**
 * Supported message types - 支持的消息类型
 */
export const SUPPORTED_MSG_TYPES = ["text", "voice"] as const;
export type SupportedMsgType = (typeof SUPPORTED_MSG_TYPES)[number];

/**
 * Chat history record - 聊天历史记录
 */
export interface ChatHistoryRecord {
  recordId: string;
  botId: string;
  conversation: string;
  role: "user" | "assistant";
  content: string;
  type: string;
  triggerSrc: string;
  sender: string;
  needAsyncReply: boolean;
  reply: string;
  originMsg: string;
  recommendQuestions: string[];
  createdAt: number;
  // Optional fields
  image?: string;
  status?: string;
  traceId?: string;
  asyncReply?: string;
  replyTo?: string;
  event?: string;
}

/**
 * Processed message data - 处理后的消息数据
 */
export interface ProcessedMsgData {
  msgData: ChatHistoryRecord;
  replyMsgData: ChatHistoryRecord;
}

/**
 * Message validation result - 消息校验结果
 */
export interface MessageValidationResult {
  isValid: boolean;
  skipAI: boolean;
  errorMessage?: string;
  userErrorMessage?: string;
}

/**
 * Voice message handler type - 语音消息处理器类型
 */
export type VoiceMessageHandler = (
  botId: string,
  triggerSrc: string,
  mediaId: string
) => Promise<{ content: string } | null>;

// ============================================================================
// Message Validation - 消息校验
// ============================================================================

/**
 * Validate message type - 校验消息类型
 */
export function validateMessageType(msgType: string): MessageValidationResult {
  if (SUPPORTED_MSG_TYPES.includes(msgType as SupportedMsgType)) {
    return { isValid: true, skipAI: false };
  }
  return {
    isValid: false,
    skipAI: true,
    errorMessage: `无法处理的消息类型:${msgType}`,
    userErrorMessage: "抱歉暂时无法处理这个类型的消息",
  };
}

/**
 * Extract message type from origin message - 从原始消息提取消息类型
 */
export function extractMsgType(originMsg: any): string {
  return originMsg.msgType || originMsg.MsgType || "text";
}

/**
 * Extract trigger source from origin message - 从原始消息提取触发源
 */
export function extractTriggerSrc(
  originMsg: any,
  defaultSrc: WeChatTriggerSrc = WeChatPlatform.SERVICE
): WeChatTriggerSrc {
  return originMsg.triggerSrc || defaultSrc;
}

// ============================================================================
// Content Extraction - 内容提取
// ============================================================================

/**
 * Extract text content from WeChat message - 从微信消息提取文本内容
 */
export function extractTextContent(
  originMsg: any,
  triggerSrc: WeChatTriggerSrc
): string {
  if (
    [
      WeChatPlatform.SUBSCRIPTION,
      WeChatPlatform.SERVICE,
      WeChatPlatform.MINI_APP,
    ].includes(triggerSrc)
  ) {
    return originMsg.Content || originMsg.content || "";
  } else if (triggerSrc === WeChatPlatform.CUSTOM_SERVICE) {
    return originMsg.text?.content || "";
  }
  return "";
}

/**
 * Extract voice media ID from WeChat message - 从微信消息提取语音媒体ID
 */
export function extractVoiceMediaId(
  originMsg: any,
  triggerSrc: WeChatTriggerSrc
): string {
  if (
    [WeChatPlatform.SUBSCRIPTION, WeChatPlatform.SERVICE].includes(triggerSrc)
  ) {
    return originMsg.MediaId || originMsg.mediaId || "";
  } else if (triggerSrc === WeChatPlatform.CUSTOM_SERVICE) {
    return originMsg.voice?.mediaId || "";
  }
  return "";
}

/**
 * Get content from WeChat message (text or voice) - 获取微信消息内容
 */
export async function getWxChatContent(
  originMsg: any,
  triggerSrc: WeChatTriggerSrc,
  voiceMessageHandler?: VoiceMessageHandler,
  botId?: string
): Promise<string> {
  const msgType = extractMsgType(originMsg);

  // Text message
  if (msgType === "text") {
    return extractTextContent(originMsg, triggerSrc);
  }

  // Voice message
  if (msgType === "voice") {
    const mediaId = extractVoiceMediaId(originMsg, triggerSrc);
    if (voiceMessageHandler && mediaId && botId) {
      const result = await voiceMessageHandler(botId, triggerSrc, mediaId);
      return result?.content || "";
    }
  }

  return "";
}

// ============================================================================
// Sender & Conversation Extraction - 发送者和会话提取
// ============================================================================

/**
 * Extract sender from origin message - 从原始消息提取发送者
 */
export function extractSender(
  originMsg: any,
  triggerSrc: WeChatTriggerSrc
): string {
  if (
    [
      WeChatPlatform.SUBSCRIPTION,
      WeChatPlatform.SERVICE,
      WeChatPlatform.MINI_APP,
    ].includes(triggerSrc)
  ) {
    return originMsg.FromUserName || originMsg.fromUserName || "";
  } else if (triggerSrc === WeChatPlatform.CUSTOM_SERVICE) {
    return originMsg.externalUserId || "";
  }
  return "";
}

/**
 * Extract conversation ID from origin message - 从原始消息提取会话ID
 */
export function extractConversation(
  originMsg: any,
  triggerSrc: WeChatTriggerSrc
): string {
  if (
    [
      WeChatPlatform.SUBSCRIPTION,
      WeChatPlatform.SERVICE,
      WeChatPlatform.MINI_APP,
    ].includes(triggerSrc)
  ) {
    return originMsg.FromUserName || originMsg.fromUserName || "";
  } else if (triggerSrc === WeChatPlatform.CUSTOM_SERVICE) {
    return originMsg.externalUserId || "";
  }
  return "";
}

// ============================================================================
// Record ID Generation - 记录ID生成
// ============================================================================

/**
 * Generate record ID - 生成记录ID
 */
export function generateRecordId(
  triggerSrc: WeChatTriggerSrc,
  msgId: string,
  timestamp: number
): string {
  return `${triggerSrc}${msgId}${timestamp}`;
}

/**
 * Extract message ID from origin message - 从原始消息提取消息ID
 */
export function extractMsgId(originMsg: any): string {
  return originMsg.msgId || originMsg.MsgId || Date.now().toString();
}

/**
 * Extract timestamp from origin message - 从原始消息提取时间戳
 */
export function extractTimestamp(
  originMsg: any,
  triggerSrc: WeChatTriggerSrc
): number {
  if (triggerSrc === WeChatPlatform.CUSTOM_SERVICE) {
    return originMsg.sendTime || Math.floor(Date.now() / 1000);
  }
  return (
    originMsg.createTime ||
    originMsg.CreateTime ||
    Math.floor(Date.now() / 1000)
  );
}

// ============================================================================
// Async Reply Logic - 异步回复逻辑
// ============================================================================

/**
 * Determine if async reply is needed - 判断是否需要异步回复
 */
export function needAsyncReply(
  triggerSrc: WeChatTriggerSrc,
  wxVerify: boolean
): boolean {
  // 小程序和企业微信客服始终异步
  if (
    [WeChatPlatform.MINI_APP, WeChatPlatform.CUSTOM_SERVICE].includes(
      triggerSrc
    )
  ) {
    return true;
  }
  // 公众号/服务号根据认证状态决定
  return wxVerify;
}

// ============================================================================
// Reply Message Formatting - 回复消息格式化
// ============================================================================

/**
 * WeChat reply message structure
 */
export interface WeChatReplyMessage {
  toUserName: string;
  fromUserName: string;
  createTime: number;
  msgType: string;
  content: string;
  msgId: string;
  openKfId?: string;
}

/**
 * Format reply message for WeChat
 * Used for both sync HTTP response and async aitools sending
 */
export function formatWeChatReplyMessage(
  callbackData: any,
  triggerSrc: string,
  content: string
): WeChatReplyMessage {
  const createTime = Math.floor(Date.now() / 1000);
  const finalContent = content || "抱歉暂时无法处理这个类型的消息";

  // WeChat Work Customer Service
  if (triggerSrc === WeChatPlatform.CUSTOM_SERVICE) {
    return {
      toUserName: callbackData.externalUserId || callbackData.fromUserName,
      fromUserName: callbackData.openKfId,
      openKfId: callbackData.openKfId,
      createTime,
      msgType: "text",
      content: finalContent,
      msgId: callbackData.msgId,
    };
  }

  // WeChat Official Account / Service Account / Mini Program
  return {
    toUserName: callbackData.fromUserName || callbackData.FromUserName,
    fromUserName: callbackData.toUserName || callbackData.ToUserName,
    createTime,
    msgType: "text",
    content: finalContent,
    msgId: callbackData.msgId,
  };
}

// ============================================================================
// Deal Message Data - 消息数据处理（核心方法）
// ============================================================================

/**
 * Deal message data - 处理微信消息，生成 msgData 和 replyMsgData
 * 完整实现原 chat_wx.service.ts 中的 dealMsgData 逻辑
 */
export function dealMsgData(
  originMsg: WxSendMessageInput["callbackData"],
  triggerSrc: WeChatTriggerSrc,
  wxVerify: boolean,
  botId: string
): ProcessedMsgData {
  const baseMsgData = {
    type: "text",
    triggerSrc: triggerSrc,
    botId: botId,
    recommendQuestions: [] as string[],
    content: "",
    originMsg: "",
    createdAt: Date.now(),
  };

  const sender = extractSender(originMsg, triggerSrc);
  const conversation = extractConversation(originMsg, triggerSrc);
  const msgId = extractMsgId(originMsg);
  const timestamp = extractTimestamp(originMsg, triggerSrc);
  const recordIdBase = generateRecordId(triggerSrc, msgId, timestamp);
  const asyncReply = needAsyncReply(triggerSrc, wxVerify);
  const msgType = extractMsgType(originMsg);

  return {
    msgData: {
      ...baseMsgData,
      recordId: `user-${recordIdBase}`,
      role: "user" as const,
      sender: sender,
      conversation: conversation,
      type: msgType,
      needAsyncReply: asyncReply,
      reply: recordIdBase,
      originMsg: JSON.stringify(originMsg),
    },
    replyMsgData: {
      ...baseMsgData,
      recordId: recordIdBase,
      role: "assistant" as const,
      sender: sender,
      conversation: conversation,
      type: "text",
      needAsyncReply: asyncReply,
      reply: "",
      originMsg: JSON.stringify({}),
    },
  };
}

// ============================================================================
// WeChat Retry Logic - 微信重试逻辑
// ============================================================================

/**
 * Handle WeChat retry for unverified accounts (11-second rule)
 * 处理未认证账号的微信重试逻辑（11秒规则）
 */
export async function handleWeChatRetry(
  previousReply: HistoryEntry | null,
  originMsg: any,
  triggerSrc: WeChatTriggerSrc
): Promise<{ shouldSkip: boolean; content?: string }> {
  if (!previousReply) {
    return { shouldSkip: false };
  }

  const timestamp = extractTimestamp(originMsg, triggerSrc);
  const deltaTime = Date.now() - timestamp * 1000;

  // If already has content, return it
  if (previousReply.content) {
    return {
      shouldSkip: true,
      content: previousReply.content,
    };
  }

  // If more than 11 seconds, return status message
  if (deltaTime > 11 * 1000) {
    return {
      shouldSkip: true,
      content: '思考中，请稍后回复 "继续" 来获取回答内容',
    };
  }

  // Less than 11 seconds, sleep 5s to timeout (WeChat will retry)
  await new Promise((resolve) => setTimeout(resolve, 5000));
  return { shouldSkip: true };
}

/**
 * Check if "继续" command is within 5-minute timeout
 * 检查"继续"命令是否在5分钟超时内
 */
export function isContinueCommandValid(
  previousReply: HistoryEntry | null
): boolean {
  if (!previousReply) {
    return false;
  }
  const fiveMinutes = 5 * 60 * 1000;
  return Date.now() - previousReply.createdAt < fiveMinutes;
}
