/**
 * WeChat platform types
 */
export enum WeChatPlatform {
  /** 企业微信客服 */
  CUSTOM_SERVICE = "WXCustomerService",
  /** 微信小程序 */
  MINI_APP = "WXMiniapp",
  /** 微信服务号 */
  SERVICE = "WXService",
  /** 微信订阅号 */
  SUBSCRIPTION = "WXSubscription",
}

/**
 * Message types
 */
export enum MessageType {
  TEXT = "text",
  IMAGE = "image",
  EVENT = "event",
  VOICE = "voice",
}

/**
 * WeChat send mode
 */
export enum WeChatSendMode {
  /** Use local WeChatSender (for local development) */
  LOCAL = "local",
  /** Use aitools SDK (for cloud function environment) */
  AITOOLS = "aitools",
}

export interface WeChatConfig {
  platform: WeChatPlatform;
  appId: string;
  appSecret: string;
  openKfId?: string;
  tokenCacheTTL?: number;
  sendMode?: WeChatSendMode;
  context?: any;
}

export interface MessageContent {
  content: string;
  type: MessageType;
  imageUrl?: string;
}

export interface SendMessageOptions {
  toUser: string;
  message: MessageContent;
  recommendQuestions?: string[];
  msgId?: string;
}

export interface AccessTokenResponse {
  access_token: string;
  expires_in: number;
  errcode?: number;
  errmsg?: string;
}

export interface WeChatAPIResponse {
  errcode: number;
  errmsg: string;
  [key: string]: any;
}

export interface TokenCacheEntry {
  accessToken: string;
  expiresAt: number;
}

export interface WeChatMessage {
  touser: string;
  msgtype: string;
  text?: { content: string };
  image?: { media_id?: string; pic_url?: string };
  open_kfid?: string;
  msgid?: string;
}
