import { WeChatConfig, SendMessageOptions, WeChatAPIResponse } from "./types";
import { TokenManager } from "./token-manager";
import { MessageFormatter } from "./message-formatter";
import { PlatformRouter } from "./platform-router";

/**
 * Main WeChat sender class
 * Provides a simple API to send LLM messages to WeChat platforms
 */
export class WeChatSender {
  private config: WeChatConfig;
  private tokenManager: TokenManager;
  private messageFormatter: MessageFormatter;
  private platformRouter: PlatformRouter;

  constructor(config: WeChatConfig) {
    // Validate config
    this.config = config;

    // Initialize components
    this.tokenManager = new TokenManager();
    this.messageFormatter = new MessageFormatter();
    this.platformRouter = new PlatformRouter(this.tokenManager);
  }

  /**
   * Send a message to WeChat
   */
  async send(
    options: SendMessageOptions,
    originMsg?: any
  ): Promise<WeChatAPIResponse> {
    // Validate options
    const validatedOptions = options;

    // Format message
    const message = this.messageFormatter.formatMessage(
      validatedOptions,
      this.config.platform,
      originMsg
    );

    // Send message
    const result = await this.platformRouter.send(message, this.config);

    // Check for errors
    if (result.errcode !== 0) {
      throw new Error(`Failed to send message: ${result.errmsg}`);
    }

    return result;
  }

  /**
   * Send multiple messages in batch
   */
  async sendBatch(
    messages: SendMessageOptions[]
  ): Promise<WeChatAPIResponse[]> {
    const results: WeChatAPIResponse[] = [];

    for (const message of messages) {
      try {
        const result = await this.send(message);
        results.push(result);
      } catch (error) {
        results.push({
          errcode: -1,
          errmsg: error instanceof Error ? error.message : "Unknown error",
        });
      }
    }

    return results;
  }

  /**
   * Send message asynchronously (fire and forget)
   */
  async sendAsync(options: SendMessageOptions, originMsg?: any): Promise<void> {
    this.send(options, originMsg).catch((error) => {
      console.error("Failed to send message:", error);
    });
  }

  /**
   * Clear token cache
   */
  clearCache(): void {
    this.tokenManager.clearCache(this.config);
  }

  /**
   * Get current configuration
   */
  getConfig(): WeChatConfig {
    return { ...this.config };
  }
}
