import {
  WeChatConfig,
  WeChatPlatform,
  AccessTokenResponse,
  TokenCacheEntry,
} from "./types";

/**
 * Token manager for WeChat access tokens
 * Handles token caching and automatic refresh
 */
export class TokenManager {
  private cache: Map<string, TokenCacheEntry> = new Map();

  /**
   * Get access token (with caching)
   */
  async getAccessToken(config: WeChatConfig): Promise<string> {
    const cacheKey = this.getCacheKey(config);
    const cached = this.cache.get(cacheKey);

    // Return cached token if still valid
    if (cached && cached.expiresAt > Date.now()) {
      return cached.accessToken;
    }

    // Fetch new token
    const token = await this.fetchAccessToken(config);
    return token;
  }

  /**
   * Fetch access token from WeChat API
   */
  private async fetchAccessToken(config: WeChatConfig): Promise<string> {
    const url = this.getTokenUrl(config);
    const response = await fetch(url);
    const data: AccessTokenResponse = await response.json();

    if (data.errcode && data.errcode !== 0) {
      throw new Error(`Failed to get access token: ${data.errmsg}`);
    }

    // Cache token with 5-minute early expiration
    const cacheKey = this.getCacheKey(config);
    const expiresAt = Date.now() + (data.expires_in - 300) * 1000;

    this.cache.set(cacheKey, {
      accessToken: data.access_token,
      expiresAt,
    });

    return data.access_token;
  }

  /**
   * Get token URL based on platform
   */
  private getTokenUrl(config: WeChatConfig): string {
    if (config.platform === WeChatPlatform.CUSTOM_SERVICE) {
      return `https://qyapi.weixin.qq.com/cgi-bin/gettoken?corpid=${config.appId}&corpsecret=${config.appSecret}`;
    }
    return `https://api.weixin.qq.com/cgi-bin/token?grant_type=client_credential&appid=${config.appId}&secret=${config.appSecret}`;
  }

  /**
   * Generate cache key
   */
  private getCacheKey(config: WeChatConfig): string {
    return `${config.platform}_${config.appId}`;
  }

  /**
   * Clear token cache
   */
  clearCache(config?: WeChatConfig): void {
    if (config) {
      this.cache.delete(this.getCacheKey(config));
    } else {
      this.cache.clear();
    }
  }
}

